import axios from 'axios';

const BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const api = axios.create({
  baseURL: `${BASE_URL}/api/v1`,
  headers: { 'Content-Type': 'application/json' },
});

// Mock data for development
const mockAppointments = [
  {
    appointmentId: 'APT-001',
    patientId: 'patient-001',
    providerId: 'provider-001',
    serviceType: 'General Checkup',
    scheduledTime: '2026-04-30T10:00:00Z',
    status: 'Scheduled',
    notes: 'Annual physical examination'
  },
  {
    appointmentId: 'APT-002',
    patientId: 'patient-001',
    providerId: 'provider-002',
    serviceType: 'Dental Cleaning',
    scheduledTime: '2026-05-05T14:30:00Z',
    status: 'Scheduled',
    notes: 'Routine dental cleaning'
  },
  {
    appointmentId: 'APT-003',
    patientId: 'patient-001',
    providerId: 'provider-001',
    serviceType: 'Follow-up',
    scheduledTime: '2026-04-15T09:00:00Z',
    status: 'Completed',
    notes: 'Post-surgery follow-up'
  },
  {
    appointmentId: 'APT-004',
    patientId: 'patient-001',
    providerId: 'provider-003',
    serviceType: 'Blood Test',
    scheduledTime: '2026-04-20T11:00:00Z',
    status: 'Cancelled',
    notes: 'Patient requested cancellation'
  }
];

// Attach JWT token to all requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('medibook_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Appointment endpoints
export const appointmentService = {
  book: (data) => api.post('/appointments', data),
  getById: (id) => api.get(`/appointments/${id}`),
  getByPatient: (patientId) => {
    // Return mock data for development
    return Promise.resolve({ data: mockAppointments.filter(a => a.patientId === patientId) });
  },
  getUpcomingByPatient: (patientId) => {
    const upcoming = mockAppointments.filter(a => 
      a.patientId === patientId && a.status === 'Scheduled'
    );
    return Promise.resolve({ data: upcoming });
  },
  getByProvider: (providerId) => api.get(`/appointments/provider/${providerId}`),
  getByProviderAndDate: (providerId, date) =>
    api.get(`/appointments/provider/${providerId}/date/${date}`),
  cancel: (id) => api.put(`/appointments/${id}/cancel`),
  reschedule: (id, data) => api.put(`/appointments/${id}/reschedule`, data),
  complete: (id) => api.put(`/appointments/${id}/complete`),
  updateStatus: (id, status) => api.put(`/appointments/${id}/status`, JSON.stringify(status)),
  getProviderCount: (providerId) => api.get(`/appointments/provider/${providerId}/count`),
};

export default api;
